INSERT INTO `oc_t_preference` (`s_section`, `s_name`, `s_value`, `e_type`) VALUES
('osclass', 'widget_data_product', '{\"date\":\"2026-07-26 08:26:55\",\"data\":{\"status\":\"ERR\",\"message\":\"[0] Empty server response\",\"httpcode\":0,\"body\":\"\",\"response\":false,\"json_error_code\":0,\"json_error_message\":\"No error\"}}', 'STRING'),
('osclass', 'widget_data_product_updates', '{\"date\":\"2026-07-26 08:26:57\",\"data\":{\"last_update\":\"2026-07-25 01:00:00\",\"link_all\":\"https:\\/\\/osclasspoint.com\\/product-updates\",\"updates\":[{\"fk_i_item_id\":\"284\",\"i_version\":\"1.0.0\",\"s_osc_version_from\":\"8.0\",\"s_osc_version_to\":\"\",\"s_comment\":\"Initial plugin release\",\"s_title\":\"Slideshow Plugin\",\"s_url\":\"https:\\/\\/osclasspoint.com\\/index.php?page=item&id=284\",\"dt_date\":\"2026-07-23 10:42:36\"},{\"fk_i_item_id\":\"83\",\"i_version\":\"1.5.0\",\"s_osc_version_from\":\"8.0\",\"s_osc_version_to\":\"\",\"s_comment\":\"Major update: Custom download file names and separate item-page button vs box download UI. \\nSellers can set a display\\/download file name on upload; if empty, the original file name is used. Item page supports two outputs: a compact download button and a download box with clear status (available, login, purchase, unavailable). \\nButton and box hooks are configured separately; by default the box shows on item_detail. \\nDownload titles and saved files use the custom label when set. \\nPlugin database upgrades automatically (file name field and new hook settings). \\nGeneral stability improvements for upload size limits and category handling.\",\"s_title\":\"Virtual Products Plugin\",\"s_url\":\"https:\\/\\/osclasspoint.com\\/index.php?page=item&id=83\",\"dt_date\":\"2026-07-22 16:27:46\"},{\"fk_i_item_id\":\"60\",\"i_version\":\"1.6.4\",\"s_osc_version_from\":\"3.0\",\"s_osc_version_to\":\"\",\"s_comment\":\"Added optional setting to auto-approve premium (promoted) listings.\\nPremium listings skip admin approval on publish\\/edit and marked premium.\\nHourly sync covers payment plugins that set premium without core hooks.\\nValidation table shows clear reason codes (AUTO_VALIDATION_PREMIUM_NEW \\/ _EDIT \\/ AUTO_VALIDATION_PREMIUM).\\nRejected listings and post-reject revalidation queue are never auto-approved.\",\"s_title\":\"Item Validation Plugin\",\"s_url\":\"https:\\/\\/osclasspoint.com\\/index.php?page=item&id=60\",\"dt_date\":\"2026-07-22 16:16:13\"},{\"fk_i_item_id\":\"84\",\"i_version\":\"1.9.0\",\"s_osc_version_from\":\"3.0\",\"s_osc_version_to\":\"\",\"s_comment\":\"Major update: Article slugs are now language specific and work correctly with accents and non-Latin chars.\\nFixed slug generation so diacritics are converted properly (e.g. \\u00e1 -&gt; a, \\u0161 -&gt; s) instead of being removed; also improved support for Arabic, Russian, Vietnamese and similar languages.\\nSlug can now be set per language (same as title), so each locale can have its own URL slug.\\nAdded FAQ field to article edit (admin and front office) with [Q] \\/ [A] format validation.\\nFAQ section is shown on the article page above comments, including FAQ structured data for search\\/AI engines.\\nCategory is now visible in the admin articles list.\\nMulti-language support in sitemap.\",\"s_title\":\"Osclass Blog and News Plugin\",\"s_url\":\"https:\\/\\/osclasspoint.com\\/index.php?page=item&id=84\",\"dt_date\":\"2026-07-22 14:35:52\"},{\"fk_i_item_id\":\"281\",\"i_version\":\"1.0.1\",\"s_osc_version_from\":\"8.0\",\"s_osc_version_to\":\"\",\"s_comment\":\"Improved verification if turnstile is added to form or not.\\nImproved messages shown to users.\\nEnhanced detection of light\\/dark mode.\",\"s_title\":\"Cloudflare Turnstile reCaptcha Plugin\",\"s_url\":\"https:\\/\\/osclasspoint.com\\/index.php?page=item&id=281\",\"dt_date\":\"2026-07-22 09:53:51\"}]}}', 'STRING'),
